#include "secrets.h"
// Пины для подключения датчика HC-SR04
const int trigPin = 9;
const int echoPin = 10;

void setup() {
  // Настройка скорости передачи данных для монитора порта
  Serial.begin(9600);

  // Инициализация пинов
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
}

void loop() {
  // Очищаем пин trigPin
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);

  // Подаем высокий сигнал на пин trigPin в течение 10 микросекунд
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Считываем время возврата волны на echoPin
  long duration = pulseIn(echoPin, HIGH);

  // Вычисляем расстояние в сантиметрах
  int distance = duration * 0.034 / 2;

  // Вывод результата в монитор порта
  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  // Небольшая задержка перед следующим измерением
  delay(100);
}
